pipeline {
  agent { label 'docker' }
  stages {
    stage('Build') {
      steps { sh 'mvn -q package' }
    }
    stage('Test') {
      steps { sh 'mvn -q test' }
    }
    stage('Image') {
      steps { sh 'docker build -t registry.example.com/shop/api:${BUILD_NUMBER} .' }
    }
    stage('Deploy') {
      steps { sh 'kubectl set image deploy/api api=registry.example.com/shop/api:${BUILD_NUMBER}' }
    }
  }
  post { failure { echo 'Build failed' } }
}

terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
  backend "s3" {
    bucket         = "shop-tf-state"
    key            = "prod/terraform.tfstate"
    region         = "ap-south-1"
    dynamodb_table = "shop-tf-lock"
  }
}

provider "aws" {
  region = "ap-south-1"
}

resource "aws_s3_bucket" "assets" {
  bucket = "shop-assets-prod"
}

